import{_ as s,o as t,c as i,a6 as n}from"./chunks/framework.BBIckNDn.js";const u=JSON.parse('{"title":"オブジェクトファイル・実行ファイル・静的ライブラリ・動的ライブラリ・DLL","description":"","frontmatter":{"title":"オブジェクトファイル・実行ファイル・静的ライブラリ・動的ライブラリ・DLL","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"オブジェクトファイル(.o / .obj): 1翻訳単位ぶんの機械語+シンボル表。未完成品 静的ライブラリ(.a / .lib): .oを束ねた「アーカイブ」。リンク時に実行ファイルへ焼き込まれる"}},"headers":[],"relativePath":"runtime/cpp-internals/object-files-and-libraries.md","filePath":"runtime/cpp-internals/object-files-and-libraries.md"}'),e={name:"runtime/cpp-internals/object-files-and-libraries.md"};function l(r,a,o,d,p,h){return t(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="オブジェクトファイル・実行ファイル・静的ライブラリ・動的ライブラリ・dll" tabindex="-1">オブジェクトファイル・実行ファイル・静的ライブラリ・動的ライブラリ・DLL <a class="header-anchor" href="#オブジェクトファイル・実行ファイル・静的ライブラリ・動的ライブラリ・dll" aria-label="Permalink to &quot;オブジェクトファイル・実行ファイル・静的ライブラリ・動的ライブラリ・DLL&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><ul><li><strong>オブジェクトファイル(.o / .obj)</strong>: 1翻訳単位ぶんの機械語+シンボル表。未完成品</li><li><strong>静的ライブラリ(.a / .lib)</strong>: .oを束ねた「アーカイブ」。リンク時に<strong>実行ファイルへ焼き込まれる</strong></li><li><strong>動的ライブラリ(.so / .dll)</strong>: 完成品に近いバイナリ。<strong>実行時にロードして結合</strong>される</li><li><strong>実行ファイル(.exe / ELF)</strong>: ローダーが読める完成品</li></ul><h2 id="オブジェクトファイルの中身" tabindex="-1">オブジェクトファイルの中身 <a class="header-anchor" href="#オブジェクトファイルの中身" aria-label="Permalink to &quot;オブジェクトファイルの中身&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enemy.o</span></span>
<span class="line"><span>├─ .text   : 機械語(Enemy::TakeDamage の命令列など)</span></span>
<span class="line"><span>├─ .data   : 初期化済みグローバル/静的変数の初期値</span></span>
<span class="line"><span>├─ .bss    : ゼロ初期化変数の「サイズだけ」(実体は実行時に確保)</span></span>
<span class="line"><span>├─ .rodata : 定数・文字列リテラル</span></span>
<span class="line"><span>├─ シンボル表: 提供する名前 / 必要とする名前(未解決)</span></span>
<span class="line"><span>└─ 再配置情報: 「この命令のこの部分は、後でXのアドレスを書き込む」のリスト</span></span></code></pre></div><p>「未解決の名前」と「再配置情報」があるから未完成品であり、それを埋めるのが<a href="/study/runtime/cpp-internals/build-pipeline-journey.html">リンカ</a>です。</p><h2 id="静的ライブラリ-vs-動的ライブラリ" tabindex="-1">静的ライブラリ vs 動的ライブラリ <a class="header-anchor" href="#静的ライブラリ-vs-動的ライブラリ" aria-label="Permalink to &quot;静的ライブラリ vs 動的ライブラリ&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>静的リンク:                          動的リンク:</span></span>
<span class="line"><span>game.exe                            game.exe ──実行時に参照──&gt; physics.dll</span></span>
<span class="line"><span> ├─ main.o                           ├─ main.o                  (別ファイルのまま)</span></span>
<span class="line"><span> ├─ physics.a の中の使われた.o        └─ 「physics.dllのSimulateを使う」という記録</span></span>
<span class="line"><span> └─ ...(全部入り・自己完結)</span></span></code></pre></div><table tabindex="0"><thead><tr><th></th><th>静的リンク</th><th>動的リンク(DLL/.so)</th></tr></thead><tbody><tr><td>実行ファイル</td><td>大きい(全部入り)</td><td>小さい(参照だけ)</td></tr><tr><td>起動・実行</td><td>速い・自己完結</td><td>ロードの手間、ファイルが欠けると起動不能</td></tr><tr><td>更新</td><td>再ビルド・再配布が必要</td><td><strong>DLL差し替えだけで更新可</strong>(パッチ、プラグイン)</td></tr><tr><td>複数プログラムでの共有</td><td>各自にコピー</td><td>メモリ・ディスクを共有できる</td></tr><tr><td>最適化</td><td>LTO(リンク時最適化)でライブラリ境界を越えたインライン化が可能</td><td>境界を越えた最適化は不可</td></tr><tr><td>ABI問題</td><td>ビルド時に固定(比較的安全)</td><td><strong>実行時に一致が必要</strong>(→ 下記)</td></tr></tbody></table><ul><li>静的ライブラリのリンクは「<strong>使われた.oだけ</strong>取り込む」(アーカイブ全体ではない)。「リンクしたのにシンボルが見つからない」の一因はリンク順・参照順(→ <a href="/study/tools/build/link-errors.html">リンクエラー</a>)</li><li>Windowsでは動的リンクでも**インポートライブラリ(.lib)**をリンク時に使う(「このDLLにこの関数がある」という目録)。「.libには静的ライブラリとインポートライブラリの2種類がある」ことは混乱の名所</li></ul><h2 id="dllの実務-windows-ゲーム" tabindex="-1">DLLの実務(Windows/ゲーム) <a class="header-anchor" href="#dllの実務-windows-ゲーム" aria-label="Permalink to &quot;DLLの実務(Windows/ゲーム)&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// DLL側: 公開する関数に印を付ける(Windows)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;C&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> __declspec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dllexport) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PluginVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 使う側(暗黙リンク): ヘッダー+インポートライブラリで普通の関数のように呼ぶ</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 使う側(明示ロード): LoadLibrary(&quot;plugin.dll&quot;) → GetProcAddress(&quot;PluginVersion&quot;)</span></span></code></pre></div><ul><li><strong>C++の型・クラスをDLL境界で渡すのはABIの罠</strong>(→ <a href="/study/runtime/cpp-internals/symbols-and-linkage.html">前ページ</a>)。異なるコンパイラ/設定/CRTでビルドされたDLLとexeの間でstd::stringやnew/deleteの所有権を渡すと壊れる。<strong>境界はC ABI+プレーンなデータ</strong>が鉄則</li><li>「確保したモジュールが解放する」(DLL内でnewしたものはDLLが提供する解放関数へ返す)と、異なるCRTの状態やアロケータをまたぐ事故を避けやすい。すべてのDLLが常に別ヒープを持つという意味ではない。同じCRTを共有する構成でも、カスタムヒープなどの契約は確認する(<a href="https://learn.microsoft.com/en-us/cpp/c-runtime-library/potential-errors-passing-crt-objects-across-dll-boundaries" target="_blank" rel="noreferrer">Microsoftの注意事項</a>)</li></ul><h2 id="ゲーム開発での使われ方" tabindex="-1">ゲーム開発での使われ方 <a class="header-anchor" href="#ゲーム開発での使われ方" aria-label="Permalink to &quot;ゲーム開発での使われ方&quot;">​</a></h2><ul><li><strong>エンジン・ミドルウェアの配布形態</strong>: FMOD/Steamworks等はDLL+Cヘッダ(まさにABI安全策)</li><li><strong>ホットリロード</strong>: ゲームロジックをDLL化し、実行中に差し替えて反映(開発イテレーション高速化)。UEのLive Codingもモジュール(DLL)差し替えが基盤(→ <a href="/study/game/unreal/build-system-ubt.html">第10部</a>)</li><li><strong>プラグイン/MOD</strong>: 明示ロード(LoadLibrary)+extern &quot;C&quot;エントリポイント</li><li>コンソール機では静的リンクが基本(単一実行ファイル文化)——プラットフォームで流儀が変わる</li></ul><h2 id="c-との対応" tabindex="-1">C#との対応 <a class="header-anchor" href="#c-との対応" aria-label="Permalink to &quot;C#との対応&quot;">​</a></h2><ul><li>C#の通常のマネージド.dllはIL+メタデータを持つ<a href="https://learn.microsoft.com/en-us/dotnet/standard/assembly/" target="_blank" rel="noreferrer">アセンブリ</a>で、ネイティブDLLとはロード・型参照の仕組みが異なる。<strong>対象フレームワーク/API・アセンブリの版・依存関係などの互換性は必要</strong>で、ネイティブ相互運用にはCPU/ABIの条件もある。「UnityのManaged DLL」と「ネイティブDLL」は拡張子だけでは区別できない</li><li>Unityの <code>Plugins/</code> フォルダのネイティブプラグイン(.dll/.so/.dylib)がこのページの動的ライブラリで、P/Invoke(<code>[DllImport]</code>)がGetProcAddressに相当</li><li>Assembly Definition(.asmdef)は「C#コードの静的ライブラリ分割」に似た開発時の構造化(→ <a href="/study/languages/csharp/headers-vs-asmdef.html">第9部</a>)</li></ul><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li>「DLLを置けば動く」— ネイティブDLLはプラットフォーム・アーキテクチャ(x64/ARM64)・依存DLL(VCランタイム等)の一致が必要</li><li>C# DLLの感覚でネイティブDLLにクラスを公開しようとする——境界はCの関数とデータに落とすのが定石</li><li>「実行ファイルは1つの塊」— 実際は起動時に多数のDLL(システム・ドライバ層含む)と結合されて動いている(Process Explorer等で見られる)</li></ol><h2 id="使う場面-使わない場面" tabindex="-1">使う場面 / 使わない場面 <a class="header-anchor" href="#使う場面-使わない場面" aria-label="Permalink to &quot;使う場面 / 使わない場面&quot;">​</a></h2><ul><li><strong>静的リンク</strong>: 自プロジェクトの内部分割(既定)、コンソール機、配布を単純にしたいツール</li><li><strong>動的リンク</strong>: ミドルウェアSDK、プラグイン/MOD、ホットリロード、更新パッチをexe再配布なしで当てたい場合</li><li>内部コードをむやみにDLL分割しない——境界維持(ABI・エクスポート管理)のコストは安くない</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>.oが「未完成品」である理由を2つの中身(未解決シンボル・再配置情報)で説明できますか。</li><li>静的/動的リンクのトレードオフを3つ挙げてください。</li><li>DLL境界でstd::stringを渡すことが危険な理由は?</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p><a href="/study/tools/build/samples/tu-demo.html">samples/tu_demo/</a> で <code>ar rcs libenemy.a enemy.o</code> として静的ライブラリを作り、<code>g++ main.o radar.o -L. -lenemy</code> でリンクしてください。次にリンク順を変えて(-lenemyを先頭に)エラーが出るか観察してください(GNU ldのリンク順依存の体験)。</p><hr><p>前: <a href="/study/runtime/cpp-internals/symbols-and-linkage.html">シンボルとリンケージ</a> | <a href="/study/runtime/cpp-internals/">カテゴリ目次</a> | 次: <a href="/study/runtime/cpp-internals/template-instantiation-and-inline.html">テンプレートの実体化とinlineの実際</a></p>`,27)])])}const g=s(e,[["render",l]]);export{u as __pageData,g as default};
